'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0),fmt=v=>num(v).toLocaleString('es',{maximumFractionDigits:3});
const iso=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Chicago'});
const state={businesses:[],user:null,id:0,data:null,report:null,view:'Resumen',query:'',category:'Todas',filter:'Todos',start:'',end:'',cart:[],kind:'sale',loading:false,saving:false,modalType:'',draftKey:null};
const iconPaths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',box:'m12 3 9 5v8l-9 5-9-5V8zm0 10v8M3 8l9 5 9-5m-14-3 9 5',buy:'M3 3h2l3 12h10l3-8H6M9 20h.01M18 20h.01',sale:'M4 4h8l8 8-8 8-8-8zM8 8h.01',invoice:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',move:'M3 7h17l-4-4M21 17H4l4 4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m9 1a4 4 0 0 1 0 7m4 10v-3a4 4 0 0 0-3-4',chart:'M4 20V10h4v10M10 20V4h4v16M16 20V7h4v13',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',warehouse:'M3 21V8l9-5 9 5v13M7 21V11h10v10M7 15h10M7 18h10',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',plus:'M12 4v16M4 12h16',arrow:'M7 17 17 7M7 7h10v10',alert:'m12 3 10 18H2zM12 9v5m0 3h.01',wallet:'M3 6h17v15H3zM3 6V3h14v3M15 12h5v5h-5z',check:'m5 12 4 4L19 6',edit:'m4 15 11-11 5 5L9 20H4zm10-10 5 5',undo:'M9 4 3 10l6 6M3 10h10a7 7 0 0 1 7 7',archive:'M3 3h18v5H3zM5 8v13h14V8m-10 4h6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 5v5l3 2'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.box}"/></svg>`;
const modules=[['Resumen','grid',false],['Inventario','box',false],['Compras','buy',true],['Ventas','sale',false],['Facturación','invoice',false],['Movimientos','move',true],['Almacenes','warehouse',true],['Contactos','users',false],['Reportes','chart',true],['Equipo y permisos','shield',true],['Bitácora','clock',true],['Configuración','settings',true]];
const kinds={sale:'Venta',purchase:'Compra',adjustment:'Ajuste',transfer:'Traslado',return:'Devolución'};
const statuses={pending:['Pendiente','amber'],partial:['Pago parcial','blue'],paid:['Pagada','green'],overdue:['Vencida','red'],credit:['Nota de crédito','purple'],credited:['Con devolución','gray']};
const roles={admin:'Administrador',employee:'Empleado'};
const methods={cash:'Efectivo',card:'Tarjeta',transfer:'Transferencia'};
const sectors=['Tienda / supermercado','Ferretería','Ropa y accesorios','Restaurante / cafetería','Hotel / mantenimiento','Belleza y cuidado personal','Otro negocio'];
const admin=()=>state.data?.role==='admin';
const money=v=>new Intl.NumberFormat('es-US',{style:'currency',currency:state.data?.business.currency||'USD'}).format(num(v));
const dateLabel=v=>new Date(v).toLocaleDateString('es',{day:'2-digit',month:'short',year:'numeric'});
const button=(label,action,id='',style='secondary',ico='')=>`<button type="button" class="button ${style}" data-action="${action}" data-id="${esc(id)}">${ico?icon(ico,17):''}${label}</button>`;
const pill=(text,color='green')=>`<span class="badge ${color}">${esc(text)}</span>`;
function input(name,label,value='',type='text',attrs=''){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function select(name,label,options,value=''){return `<label class="field">${esc(label)}<select name="${name}">${options.map(o=>{const pair=Array.isArray(o)?o:[o,o];return `<option value="${esc(pair[0])}" ${String(value)===String(pair[0])?'selected':''}>${esc(pair[1])}</option>`}).join('')}</select></label>`}
function area(name,label,value='',required=false){return `<label class="field">${esc(label)}<textarea name="${name}" maxlength="500" ${required?'required':''}>${esc(value)}</textarea></label>`}
function empty(title,description='',action=''){return `<div class="empty">${icon('box',36)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">TU NEGOCIO, EN ORDEN</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`}
function stat(label,value,sub,ico,color=''){return `<article class="stat ${color}"><div><span>${esc(label)}</span><span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong><small>${esc(sub)}</small></article>`}
function form(id,content,label='Guardar cambios'){return `<form id="${id}" class="form-stack">${content}<div class="form-footer"><span class="save-hint">Los cambios se guardan al confirmar.</span><button class="button primary" type="submit">${icon('check',17)}${label}</button></div></form>`}
function setError(message,modal=false){const el=$(modal?'#modal-error':'#global-error');el.textContent=message;el.hidden=!message}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{'X-CSRFToken':$('#csrf-source input').value,...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});const j=r.headers.get('Content-Type')?.includes('application/json')?await r.json():{error:'No se pudo completar la solicitud. Actualiza la página y vuelve a intentar.'};if(!r.ok){if(r.status===401){location.assign('/login/');throw Error('Sesión finalizada.')}if(j.must_change_password)passwordModal();throw Error(j.error||'No se pudo completar la operación.')}return j}
async function initialize(id){setError('');try{const me=await api('/api/me/');state.user=me.user;state.businesses=me.businesses;state.id=num(id||state.id||me.businesses[0]?.id);if(!state.id){$('#page').innerHTML=empty('Tu cuenta no tiene negocios activos','Solicita acceso al administrador.');return}await load();}catch(e){setError(e.message)}}
async function load(){state.loading=true;setError('');try{const id=state.id;const data=await api(`/api/b/${id}/state/`);if(id!==state.id)return;state.data=data;const r=await api(`/api/b/${id}/report/?${new URLSearchParams({...(state.start?{start:state.start}:{}),...(state.end?{end:state.end}:{})})}`);if(id!==state.id)return;state.report=r;renderChrome();render()}catch(e){setError(e.message);throw e}finally{state.loading=false}}
function renderChrome(){$('#business-select').innerHTML=state.businesses.map(b=>`<option value="${b.id}" ${b.id===state.id?'selected':''}>${esc(b.name)}</option>`).join('');$('#role-label').textContent=roles[state.data.role];$('#profile-name').innerHTML=esc(state.user.name)+`<small>${roles[state.data.role]}</small>`;$('.avatar').textContent=state.user.name.slice(0,2).toUpperCase();$('#new-business').hidden=!admin();$('#footer-business').textContent=state.data.business.name+' · '+state.data.business.currency;$('#navigation').innerHTML=modules.filter(m=>!m[2]||admin()).map(([name,ico])=>`<button class="nav-button ${state.view===name?'active':''}" data-action="nav" data-id="${name}">${icon(ico)}<span>${name}</span>${name==='Facturación'&&state.data.invoices.some(i=>['overdue','pending','partial'].includes(i.status))?'<i></i>':''}</button>`).join('')}
function navigate(view){const mod=modules.find(m=>m[0]===view);if(!mod||mod[2]&&!admin())view='Resumen';state.view=view;state.query='';state.category='Todas';state.filter='Todos';$('#sidebar').classList.remove('is-open');renderChrome();render();window.scrollTo({top:0})}
function productImage(p,large=false){return p.has_photo?`<img class="product-photo ${large?'large':''}" src="/api/b/${state.id}/products/${p.id}/photo/?v=${p.version}" alt="${esc(p.name)}" loading="lazy">`:`<span class="product-placeholder tone-${p.category.length%4} ${large?'large':''}">${icon('box',large?42:21)}</span>`}
function stockBadge(p){return !p.active?pill('Archivado','gray'):num(p.stock)===0?pill('Agotado','red'):num(p.stock)<=num(p.minimum)?pill('Stock bajo','amber'):pill('Disponible','green')}
function productsTable(products){return `<div class="table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th><th class="numeric">Existencias</th>${admin()?'<th class="numeric">Costo promedio</th>':''}<th class="numeric">Precio</th><th>Estado</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="product-cell">${productImage(p)}<div><button class="product-name" data-action="product-detail" data-id="${p.id}">${esc(p.name)}</button><small>${esc(p.sku)} · ${esc(p.location||'Sin ubicación')}</small></div></div></td><td>${esc(p.category)}</td><td class="numeric"><b>${fmt(p.stock)}</b><small>${esc(p.unit)} · mín. ${fmt(p.minimum)}</small></td>${admin()?`<td class="numeric">${money(p.cost)}</td>`:''}<td class="numeric">${money(p.price)}</td><td>${stockBadge(p)}</td><td>${admin()?`<button class="icon-button" aria-label="Editar ${esc(p.name)}" data-action="product" data-id="${p.id}">${icon('edit',17)}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function chart(){const r=state.report;if(!r?.daily.length)return empty('Aún no hay ventas en el período','Al registrar operaciones verás su evolución.');const max=Math.max(...r.daily.map(d=>num(d.value)),1);const rows=r.daily.slice(-31);return `<div class="bar-chart">${rows.map(d=>`<div class="bar-item" title="${esc(d.date)}: ${money(d.value)}"><b>${money(d.value)}</b><div class="bar-track"><i style="height:${Math.max(3,num(d.value)/max*100)}%"></i></div><span>${new Date(d.date+'T12:00:00').toLocaleDateString('es',{day:'2-digit',month:'short'})}</span></div>`).join('')}</div>`}
function overview(){const d=state.data,r=state.report,active=d.products.filter(p=>p.active),low=active.filter(p=>num(p.stock)<=num(p.minimum));const health=active.length?Math.round((active.length-low.length)/active.length*100):0;return heading('Vista general',new Date().toLocaleDateString('es',{weekday:'long',day:'numeric',month:'long'}),admin()?button('Nuevo producto','product','','primary','plus'):button('Registrar venta','nav','Ventas','primary','sale'))+`<div class="stats">${admin()?stat('Valor del inventario',money(r.inventory),'A costo promedio','wallet'):stat('Mis ventas del período',money(r.sales),'Sin impuestos','wallet')}${stat('Productos activos',active.length,'En el catálogo de este negocio','box')}${admin()?stat('Ventas del período',money(r.sales),r.sale_count+' operaciones · sin impuestos','sale'):stat('Mis operaciones',r.sale_count,'Ventas realizadas por mi cuenta','sale')}${stat('Por reponer',low.length,'Productos en stock mínimo o inferior','alert','attention')}</div><div class="overview-grid"><section class="panel"><div class="panel-heading"><h2>Ventas por día</h2><span class="muted">${dateLabel(r.start+'T12:00:00')} — ${dateLabel(r.end+'T12:00:00')}</span></div>${chart()}</section><div class="overview-side"><section class="panel"><div class="panel-heading"><h2>Acciones rápidas</h2></div><div class="quick-actions">${admin()?`<button data-action="transaction" data-id="purchase"><span class="quick-icon green">${icon('buy')}</span><span><b>Registrar compra</b><small>Recibir nuevos productos</small></span>›</button>`:''}<button data-action="nav" data-id="Ventas"><span class="quick-icon blue">${icon('sale')}</span><span><b>Registrar venta</b><small>Vender y emitir factura</small></span>›</button>${admin()?`<button data-action="transaction" data-id="adjustment"><span class="quick-icon purple">${icon('move')}</span><span><b>Ajustar existencias</b><small>Registrar diferencias de conteo</small></span>›</button>`:''}</div></section><section class="panel health"><div><h2>Salud del inventario</h2>${icon('shield')}</div><strong>${health}%</strong><p>de productos sobre el mínimo</p><div class="health-bar"><i style="width:${health}%"></i></div><small>${low.length} productos necesitan reposición</small></section></div></div><section class="panel"><div class="panel-heading"><div><h2>Productos a revisar</h2><p>Prioriza tu próxima reposición.</p></div><button class="text-button" data-action="nav" data-id="Inventario">Ver inventario ›</button></div>${active.length?productsTable([...active].sort((a,b)=>(num(a.stock)-num(a.minimum))-(num(b.stock)-num(b.minimum))).slice(0,5)):empty('Crea tu primer producto','Tu catálogo está listo para comenzar.',admin()?button('Agregar producto','product','','primary','plus'):'')}</section>`}
function inventory(){const d=state.data,shown=d.products.filter(p=>(state.filter==='Archivados'?!p.active:p.active)&&(state.category==='Todas'||p.category===state.category)&&(state.filter!=='Stock bajo'||num(p.stock)<=num(p.minimum))&&(state.filter!=='Agotados'||num(p.stock)===0)&&[p.name,p.sku,p.location].join(' ').toLowerCase().includes(state.query.toLowerCase()));return heading('Inventario','Cada producto, su ubicación y sus existencias.',admin()?button('Exportar','export','inventory','secondary','download')+button('Nuevo producto','product','','primary','plus'):'')+`<section class="panel"><div class="filters"><label class="search">${icon('search')}<input id="search" value="${esc(state.query)}" placeholder="Buscar nombre, código o ubicación…" aria-label="Buscar productos"></label><select id="category-filter" aria-label="Categoría">${['Todas',...new Set(d.products.map(p=>p.category))].map(c=>`<option ${state.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="status-filter" aria-label="Estado">${['Todos','Stock bajo','Agotados','Archivados'].map(c=>`<option ${state.filter===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="table-caption">${shown.length} productos <span>Cantidades en la unidad de cada producto</span></div>${shown.length?productsTable(shown):empty('No hay productos en esta selección','Cambia los filtros o agrega un producto.')}</section>`}
function docTable(docs){return docs.length?`<div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Documento</th><th>Operación</th><th>Detalle</th><th>Almacén</th><th class="numeric">Total</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td>${dateLabel(d.date)}<small>${esc(d.creator)}</small></td><td><button class="product-name" data-action="document-detail" data-id="${d.id}">${esc(d.number)}</button><small>${esc(d.reference)}</small></td><td>${pill(kinds[d.kind],d.kind==='sale'?'blue':d.kind==='return'?'purple':'green')}${d.returned?'<small>Con devolución</small>':''}</td><td>${esc(d.lines.length===1?d.lines[0].name:d.lines.length+' productos')}<small>${esc(d.contact||d.note)}</small></td><td>${esc(d.warehouse)}${d.destination?'<small>→ '+esc(d.destination)+'</small>':''}</td><td class="numeric">${['adjustment','transfer'].includes(d.kind)?'—':money(d.total)}</td><td>${admin()&&d.kind==='sale'&&!d.returned?`<button class="icon-button" data-action="return" data-id="${d.id}" title="Registrar devolución">${icon('undo',17)}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin operaciones registradas','Los nuevos movimientos aparecerán aquí.')}
function purchases(){return heading('Compras','Recibe productos y actualiza el costo promedio.',button('Registrar compra','transaction','purchase','primary','plus'))+`<section class="panel"><div class="panel-heading"><h2>Historial de compras</h2><span class="muted">Hasta las últimas 250 operaciones</span></div>${docTable(state.data.documents.filter(d=>d.kind==='purchase'))}</section>`}
function sales(){const d=state.data,products=d.products.filter(p=>p.active&&[p.name,p.sku,p.category].join(' ').toLowerCase().includes(state.query.toLowerCase())&&(state.category==='Todas'||state.category===p.category));const subtotal=state.cart.reduce((sum,l)=>sum+Math.round(l.quantity*l.price*100)/100,0);const tax=state.cart.reduce((sum,l)=>sum+Math.round((Math.round(l.quantity*l.price*100)/100)*num(d.business.tax_rate))/100,0);return heading('Registrar venta','Selecciona los productos, confirma y genera la factura.',button('Ver mis ventas','sales-history','','secondary','clock'))+`<div class="pos-layout"><section><label class="search pos-search">${icon('search')}<input id="search" value="${esc(state.query)}" placeholder="Buscar producto o escanear código…" aria-label="Buscar producto"></label><div class="chips">${['Todas',...new Set(d.products.filter(p=>p.active).map(p=>p.category))].map(c=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-id="${esc(c)}">${esc(c==='Todas'?'Todos':c)}</button>`).join('')}</div><div class="product-grid">${products.map(p=>`<button class="product-tile" data-action="cart-add" data-id="${p.id}" ${num(p.stock)<=0?'disabled':''}>${productImage(p,true)}<h3>${esc(p.name)}</h3><small>${esc(p.sku)}</small><div><strong>${money(p.price)}</strong>${pill('Stock: '+fmt(p.stock),num(p.stock)<=num(p.minimum)?'amber':'green')}</div></button>`).join('')}</div>${!products.length?empty('No hay productos disponibles','Agrega productos o cambia la búsqueda.'):''}</section><section class="panel sale-cart"><div class="panel-heading"><h2>Venta actual</h2><button class="text-button danger" data-action="cart-clear">Vaciar</button></div><form id="sale-form" class="cart-form">${select('warehouse','Almacén',d.warehouses.filter(w=>w.active).map(w=>[w.id,w.name]),state.cartWarehouse||d.warehouses[0]?.id)}${select('contact','Cliente',[['','Consumidor final'],...d.contacts.filter(c=>c.kind==='customer').map(c=>[c.id,c.name])],state.cartContact||'')}<div class="cart-lines">${state.cart.length?state.cart.map(l=>`<div class="cart-line"><div><b>${esc(l.name)}</b><small>${money(l.price)} por ${esc(l.unit)}</small></div><div class="quantity-control"><button type="button" data-action="cart-minus" data-id="${l.id}" aria-label="Restar">−</button><input class="cart-qty" data-id="${l.id}" aria-label="Cantidad de ${esc(l.name)}" type="number" step="0.001" min="0.001" value="${l.quantity}"><button type="button" data-action="cart-plus" data-id="${l.id}" aria-label="Sumar">+</button></div><strong>${money(l.quantity*l.price)}</strong><button type="button" class="icon-button" data-action="cart-remove" data-id="${l.id}" aria-label="Quitar producto">×</button></div>`).join(''):'<div class="cart-empty">'+icon('sale',30)+'<p>Agrega productos para comenzar.</p></div>'}</div>${input('due_date','Fecha límite de pago',state.cartDue||iso(),'date','required min="'+iso()+'"')}${area('note','Notas (opcional)',state.cartNote||'')}<div class="totals"><div><span>Subtotal</span><b>${money(subtotal)}</b></div><div><span>Impuestos (${fmt(d.business.tax_rate)}%)</span><b>${money(tax)}</b></div><div class="grand-total"><span>Total</span><strong>${money(subtotal+tax)}</strong></div></div><button type="submit" class="button primary full" ${!state.cart.length?'disabled':''}>Confirmar venta y facturar</button><p class="form-note">El cobro se registra después en Facturación. No se procesa un cargo bancario.</p></form></section></div>`}
function invoices(){const list=state.data.invoices.filter(i=>(state.filter==='Todos'||i.status===state.filter)&&[i.number,i.customer.name].join(' ').toLowerCase().includes(state.query.toLowerCase()));const pending=state.data.invoices.reduce((s,i)=>s+num(i.balance),0);return heading('Facturación','Facturas, cobros y notas de crédito en un solo lugar.',(admin()?button('Exportar','export','invoices','secondary','download'):'')+button('Nueva venta','nav','Ventas','primary','plus'))+`<div class="invoice-info">${icon('invoice')}<span>Documentos comerciales con impuestos configurables. La autorización fiscal electrónica depende del país y aún no está integrada.</span></div><div class="stats three">${stat('Por cobrar',money(pending),'En las facturas mostradas','wallet')}${stat('Facturas pendientes',state.data.invoices.filter(i=>['pending','partial','overdue'].includes(i.status)).length,'Incluye pagos parciales','invoice')}${stat('Vencidas',state.data.invoices.filter(i=>i.status==='overdue').length,'Revisa la fecha de pago','alert','attention')}</div><section class="panel"><div class="filters"><label class="search">${icon('search')}<input id="search" value="${esc(state.query)}" placeholder="Buscar factura o cliente…" aria-label="Buscar factura"></label><select id="status-filter" aria-label="Estado"><option value="Todos">Todos los estados</option>${Object.entries(statuses).map(([key,[label]])=>`<option value="${key}" ${state.filter===key?'selected':''}>${label}</option>`).join('')}</select></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Emisión / vence</th><th class="numeric">Total</th><th class="numeric">Saldo</th><th>Estado</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td><button class="product-name" data-action="invoice-detail" data-id="${i.id}">${esc(i.number)}</button><small>${i.kind==='credit'?'Nota de crédito':'Factura'}</small></td><td>${esc(i.customer.name)}</td><td>${dateLabel(i.date)}<small>${dateLabel(i.due_date+'T12:00:00')}</small></td><td class="numeric">${money(i.total)}</td><td class="numeric">${money(i.balance)}</td><td>${pill(...statuses[i.status])}</td><td><a class="icon-button" href="/api/b/${state.id}/invoices/${i.id}/pdf/" target="_blank" rel="noopener" title="Ver PDF">${icon('download',17)}</a>${num(i.balance)>0?`<button class="text-button" data-action="payment" data-id="${i.id}">Cobrar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay facturas en esta selección','Cada venta confirmada genera su factura.')}</section><p class="footnote">Se muestran hasta 250 documentos recientes. Los reportes y las exportaciones consultan el historial completo.</p>`}
function movements(){return heading('Movimientos','Entradas, salidas, traslados y correcciones con historial.',button('Exportar historial','export','movements','secondary','download')+button('Ajustar existencias','transaction','adjustment','primary','plus'))+`<div class="chips">${['Todos',...Object.keys(kinds)].map(k=>`<button class="chip ${state.filter===k?'active':''}" data-action="doc-filter" data-id="${k}">${kinds[k]||k}</button>`).join('')}${button('Nuevo traslado','transaction','transfer','secondary','move')}</div><section class="panel">${docTable(state.data.documents.filter(d=>state.filter==='Todos'||d.kind===state.filter))}</section><p class="footnote">Últimas 250 operaciones. Una devolución conserva la venta original y emite una nota de crédito.</p>`}
function warehouses(){return heading('Almacenes','Existencias separadas y traslados entre ubicaciones.',button('Nuevo traslado','transaction','transfer','secondary','move')+button('Nuevo almacén','warehouse','','primary','plus'))+`<div class="warehouse-grid">${state.data.warehouses.map(w=>{const stocks=state.data.products.flatMap(p=>p.stocks.filter(s=>s.warehouse===w.id&&num(s.quantity)>0).map(s=>({p,s})));return `<section class="panel warehouse-card"><div class="warehouse-head"><span class="quick-icon green">${icon('warehouse',25)}</span><button class="icon-button" data-action="warehouse" data-id="${w.id}" title="Editar almacén">${icon('edit',17)}</button></div><h2>${esc(w.name)}</h2><p>${esc(w.location||'Sin dirección registrada')}</p><div class="warehouse-stats"><div><strong>${stocks.length}</strong><small>Productos con stock</small></div><div><strong>${money(stocks.reduce((s,x)=>s+num(x.s.quantity)*num(x.p.cost),0))}</strong><small>Valor a costo promedio</small></div></div>${button('Ver existencias','warehouse-stock',w.id,'secondary')}</section>`}).join('')}</div>`}
function contacts(){return heading('Contactos',admin()?'Proveedores y clientes de tu negocio.':'Directorio de clientes.',admin()?button('Nuevo contacto','contact','','primary','plus'):'')+`<section class="panel"><div class="filters"><label class="search">${icon('search')}<input id="search" value="${esc(state.query)}" placeholder="Buscar nombre, correo o teléfono…" aria-label="Buscar contacto"></label></div><div class="contacts-grid">${state.data.contacts.filter(c=>[c.name,c.email,c.phone].join(' ').toLowerCase().includes(state.query.toLowerCase())).map(c=>`<article class="contact-card"><div><span class="contact-avatar">${esc(c.name.slice(0,2).toUpperCase())}</span>${admin()?`<button class="icon-button" data-action="contact" data-id="${c.id}" aria-label="Editar contacto">${icon('edit',17)}</button>`:''}</div>${pill(c.kind==='supplier'?'Proveedor':'Cliente',c.kind==='supplier'?'blue':'green')}<h3>${esc(c.name)}</h3><p>${esc(c.email||'Sin correo')}</p><p>${esc(c.phone||'Sin teléfono')}</p><small>${esc(c.address)}</small><p class="contact-note">${esc(c.notes)}</p></article>`).join('')}</div>${!state.data.contacts.length?empty('Tu directorio está vacío','El administrador puede agregar proveedores y clientes.'):''}</section>`}
function reports(){const r=state.report;const max=Math.max(...r.categories.map(c=>num(c.value)),1);return heading('Reportes','Resultados del período y valor actual de tu inventario.',button('Exportar facturas','export','invoices','secondary','download'))+`<section class="panel report-filter"><form id="report-form"><div class="form-grid">${input('start','Desde',r.start,'date','required')}${input('end','Hasta',r.end,'date','required')}</div><button class="button primary" type="submit">Aplicar período</button></form></section><div class="stats">${stat('Ventas netas',money(r.sales),'Sin impuestos; descontadas devoluciones','sale')}${stat('Compras',money(r.purchases),'Sin impuestos','buy')}${stat('Margen bruto',money(r.margin),'Ventas menos costo de productos vendidos','chart')}${stat('Por cobrar',money(r.receivable),'Saldo actual de todas las facturas','wallet')}</div><div class="overview-grid"><section class="panel"><div class="panel-heading"><h2>Ventas por día</h2></div>${chart()}</section><section class="panel"><div class="panel-heading"><h2>Valor por categoría</h2></div><div class="category-bars">${r.categories.map(c=>`<div><div><span>${esc(c.name)}</span><b>${money(c.value)}</b></div><div class="category-track"><i style="width:${num(c.value)/max*100}%"></i></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-heading"><h2>Productos más vendidos</h2></div><div class="table-scroll"><table><thead><tr><th>#</th><th>Producto</th><th>Cantidad neta</th><th class="numeric">Ingresos sin impuestos</th></tr></thead><tbody>${r.ranking.map((r,i)=>`<tr><td><span class="rank">${i+1}</span></td><td>${esc(r.name)}</td><td>${fmt(r.quantity)} ${esc(r.unit)}</td><td class="numeric">${money(r.revenue)}</td></tr>`).join('')}</tbody></table></div></section><p class="footnote">El margen bruto no incluye gastos operativos. Las devoluciones se descuentan en la fecha en que se registran. El valor del inventario y las cuentas por cobrar muestran el saldo actual.</p>`}
function team(){return heading('Equipo y permisos','Cada persona accede solo a lo que necesita.',button('Crear usuario','user','','primary','plus'))+`<div class="permission-summary"><div><span class="quick-icon green">${icon('shield')}</span><h3>Administrador</h3><p>Todos los módulos, costos, compras, almacenes, facturas, reportes y gestión del equipo.</p></div><div><span class="quick-icon blue">${icon('users')}</span><h3>Empleado</h3><p>Consulta productos y clientes. Registra ventas con precios del catálogo y cobra sus propias facturas.</p></div></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Persona</th><th>Usuario</th><th>Rol</th><th>Acceso al negocio</th><th></th></tr></thead><tbody>${state.data.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.username)}</td><td>${pill(roles[u.role],u.role==='admin'?'green':'blue')}</td><td>${pill(u.active?'Activo':'Desactivado',u.active?'green':'gray')}</td><td>${button('Cambiar permisos','permissions',u.id,'secondary')}</td></tr>`).join('')}</tbody></table></div></section><p class="footnote">Cada cuenta nueva debe cambiar su contraseña temporal al entrar. Siempre debe permanecer un administrador activo.</p>`}
const auditLabels={'document.posted':'Operación registrada','sale.returned':'Venta devuelta','payment.recorded':'Cobro registrado','payment.voided':'Cobro anulado','product.created':'Producto creado','product.updated':'Producto actualizado','product.archived':'Producto archivado','product.restored':'Producto restaurado','product.photo':'Imagen actualizada','contact.saved':'Contacto guardado','warehouse.saved':'Almacén guardado','business.updated':'Negocio actualizado','user.created':'Usuario creado','user.permissions':'Permisos modificados','business.created':'Negocio creado'};
function auditView(){return heading('Bitácora de actividad','Quién hizo cada cambio y cuándo.')+`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Acción</th><th>Registro</th><th>Detalle</th></tr></thead><tbody>${state.data.audit.map(a=>`<tr><td>${dateLabel(a.date)}<small>${new Date(a.date).toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'})}</small></td><td>${esc(a.actor)}</td><td>${esc(auditLabels[a.action]||a.action)}</td><td>${esc(a.target)}</td><td><small>${esc(Object.entries(a.detail).map(([k,v])=>k+': '+v).join(' · '))}</small></td></tr>`).join('')}</tbody></table></div></section><p class="footnote">Últimos 150 eventos. El historial completo se conserva en la base de datos.</p>`}
function settings(){const b=state.data.business;return heading('Configuración','Adapta Nexo a tu negocio.')+`<div class="settings-grid"><section class="panel settings-card"><div class="section-title">${icon('settings',26)}<div><h2>Información del negocio</h2><p>Datos del emisor para nuevas facturas.</p></div></div>${form('settings-form',`<div class="form-grid">${input('name','Nombre comercial',b.name,'text','required maxlength="120"')}${select('sector','Tipo de negocio',sectors,b.sector)}${input('tax_id','Identificación fiscal',b.tax_id)}${select('currency','Moneda',['USD','EUR','MXN','COP','PEN'],b.currency)}${input('email','Correo',b.email,'email')}${input('phone','Teléfono',b.phone)}${input('tax_rate','Impuesto general (%)',b.tax_rate,'number','required min="0" max="100" step="0.01"')}</div>${input('address','Dirección',b.address,'text','maxlength="300"')}<p class="form-note">El porcentaje se aplica a nuevas compras y ventas. Las facturas emitidas conservan sus datos originales. La moneda no cambia después del primer movimiento.</p>`,'Guardar configuración')}</section><div><section class="panel settings-card"><h2>Exportar datos</h2><p>Archivos CSV compatibles con hojas de cálculo.</p><div class="stack-buttons">${button('Inventario completo','export','inventory','secondary','download')}${button('Historial de existencias','export','movements','secondary','download')}${button('Facturas y cobros','export','invoices','secondary','download')}</div></section><section class="panel settings-card spaced"><h2>Mi cuenta</h2><p>${esc(state.user.name)} · ${esc(state.user.username)}</p>${button('Cambiar contraseña','password','','secondary','shield')}<p class="footnote">Las copias completas de PostgreSQL se administran en el servidor. Consulta la guía de instalación incluida.</p></section></div></div>`}
function render(){if(!state.data)return;const views={'Resumen':overview,'Inventario':inventory,'Compras':purchases,'Ventas':sales,'Facturación':invoices,'Movimientos':movements,'Almacenes':warehouses,'Contactos':contacts,'Reportes':reports,'Equipo y permisos':team,'Bitácora':auditView,'Configuración':settings};$('#page').innerHTML=(views[state.view]||overview)()}
function rerenderSearch(){const el=$('#search'),pos=el?.selectionStart;render();const next=$('#search');if(next){next.focus();if(pos!==null)next.setSelectionRange(pos,pos)}}
function openModal(title,content,subtitle='',wide=false){$('#modal-title').textContent=title;$('#modal-subtitle').textContent=subtitle;$('#modal-body').innerHTML=content;$('#modal').classList.toggle('wide',wide);setError('',true);if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if(state.saving)return;if(document.body.dataset.passwordRequired==='true'){toast('Cambia tu contraseña temporal para continuar.');return;}$('#modal').close();state.modalType=''}
function passwordModal(){state.modalType='password';openModal('Cambiar contraseña',form('password-form',input('current','Contraseña actual','','password','required autocomplete="current-password"')+input('password','Nueva contraseña','','password','required minlength="12" autocomplete="new-password"')+input('confirm','Repetir nueva contraseña','','password','required minlength="12" autocomplete="new-password"')+'<p class="form-note">Usa al menos 12 caracteres. Evita contraseñas comunes y datos personales.</p>','Guardar contraseña'),'Protege el acceso a tu cuenta.')}
function productModal(id){const p=state.data.products.find(p=>p.id===num(id))||{name:'',sku:'',category:'',unit:'unidad',price:0,cost:0,minimum:5,location:'',expiry:''};state.editId=p.id;state.editVersion=p.version;state.modalType='product';openModal(p.id?'Editar producto':'Nuevo producto',form('product-form',input('name','Nombre del producto',p.name,'text','required maxlength="120"')+`<div class="form-grid">${input('sku','Código / código de barras',p.sku,'text','required maxlength="80"')}${input('category','Categoría',p.category,'text','required maxlength="80"')}${select('unit','Unidad',['unidad','kg','litro','metro','caja','paquete','par'],p.unit)}${input('price','Precio de venta ('+state.data.business.currency+')',p.price,'number','required min="0" step="0.01"')}${input('minimum','Existencia mínima',p.minimum,'number','required min="0" step="0.001"')}${input('location','Ubicación / estante',p.location)}${input('expiry','Vencimiento (opcional)',p.expiry||'','date')}${!p.id?input('cost','Costo unitario inicial',p.cost,'number','required min="0" step="0.0001"')+input('initial','Existencias iniciales',0,'number','required min="0" step="0.001"')+select('warehouse','Almacén inicial',state.data.warehouses.map(w=>[w.id,w.name])):''}</div>${p.id?'<p class="form-note">Las existencias y el costo promedio se actualizan mediante compras, ajustes y devoluciones.</p>':''}`,'Guardar producto'))}
function productDetail(id){const p=state.data.products.find(p=>p.id===num(id));if(!p)return;openModal(p.name,`<div class="product-detail"><div>${productImage(p,true)}<div><span class="eyebrow">${esc(p.sku)}</span><h3>${esc(p.name)}</h3>${stockBadge(p)}<strong>${money(p.price)}</strong><small>Precio de venta por ${esc(p.unit)}</small></div></div><div class="detail-grid"><div><small>Existencias totales</small><b>${fmt(p.stock)} ${esc(p.unit)}</b></div><div><small>Stock mínimo</small><b>${fmt(p.minimum)}</b></div><div><small>Categoría</small><b>${esc(p.category)}</b></div><div><small>Vencimiento</small><b>${p.expiry?dateLabel(p.expiry+'T12:00:00'):'Sin registrar'}</b></div>${admin()?`<div><small>Costo promedio</small><b>${money(p.cost)}</b></div>`:''}<div><small>Ubicación</small><b>${esc(p.location||'Sin ubicación')}</b></div></div><h3>Existencias por almacén</h3>${p.stocks.map(s=>`<div class="detail-line"><span>${esc(s.name)}</span><b>${fmt(s.quantity)} ${esc(p.unit)}</b></div>`).join('')}${admin()?`<div class="dialog-actions">${button('Editar','product',p.id,'primary','edit')}${button(p.active?'Archivar':'Restaurar','archive',p.id,'secondary','archive')}</div><form id="photo-form" class="form-stack" data-id="${p.id}"><label class="field">Foto del producto<input type="file" name="photo" accept="image/png,image/jpeg,image/webp" required></label><small>JPG, PNG o WebP · Hasta 2 MB</small><button class="button secondary" type="submit">Guardar foto</button></form>`:''}</div>`,'Información y disponibilidad del producto.')}
function contactModal(id){const c=state.data.contacts.find(c=>c.id===num(id))||{name:'',kind:'customer',email:'',phone:'',tax_id:'',address:'',notes:''};state.editId=c.id;openModal(c.id?'Editar contacto':'Nuevo contacto',form('contact-form',input('name','Nombre',c.name,'text','required maxlength="120"')+select('kind','Tipo',[['customer','Cliente'],['supplier','Proveedor']],c.kind)+`<div class="form-grid">${input('email','Correo',c.email,'email')}${input('phone','Teléfono',c.phone)}${input('tax_id','Identificación fiscal',c.tax_id)}</div>`+input('address','Dirección',c.address)+area('notes','Notas',c.notes),'Guardar contacto'))}
function warehouseModal(id){const w=state.data.warehouses.find(w=>w.id===num(id))||{};state.editId=w.id;openModal(w.id?'Editar almacén':'Nuevo almacén',form('warehouse-form',input('name','Nombre',w.name||'','text','required maxlength="100"')+input('location','Dirección / referencia',w.location||'','text','maxlength="200"'),'Guardar almacén'))}
function transactionModal(kind){state.kind=kind;state.txLines=[];state.txDraft={};state.draftKey=crypto.randomUUID();renderTransaction()}
function saveTxDraft(){const f=$('#transaction-form');if(f)state.txDraft={...state.txDraft,...Object.fromEntries(new FormData(f))}}
function renderTransaction(){const kind=state.kind,d=state.data;openModal(kind==='purchase'?'Registrar compra':kind==='transfer'?'Trasladar existencias':'Ajustar inventario',form('transaction-form',`<div class="form-grid">${select('warehouse',kind==='transfer'?'Almacén de origen':'Almacén',d.warehouses.filter(w=>w.active).map(w=>[w.id,w.name]),state.txDraft.warehouse||d.warehouses[0]?.id)}${kind==='transfer'?select('destination','Almacén de destino',d.warehouses.filter(w=>w.active).map(w=>[w.id,w.name]),state.txDraft.destination||d.warehouses[1]?.id):kind==='purchase'?select('contact','Proveedor',[['','Sin proveedor'],...d.contacts.filter(c=>c.kind==='supplier').map(c=>[c.id,c.name])],state.txDraft.contact||''):''}${kind==='purchase'?input('reference','Referencia del comprobante',state.txDraft.reference||''):''}</div><div class="tx-add"><select id="tx-product" aria-label="Seleccionar producto"><option value="">Agregar producto…</option>${d.products.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.sku)}</option>`).join('')}</select></div>${kind==='adjustment'?'<p class="adjust-note">Indica cuánto sumar o restar, no la existencia final. Ejemplo: −2 descuenta dos unidades.</p>':''}<div class="tx-lines">${state.txLines.map(l=>`<div class="tx-line"><div><b>${esc(l.name)}</b><small>${esc(l.unit)}</small></div><label class="field">${kind==='adjustment'?'Cambio (+/−)':'Cantidad'}<input class="tx-quantity" data-id="${l.id}" type="number" step="0.001" ${kind!=='adjustment'?'min="0.001"':''} value="${l.quantity}" required></label>${kind==='purchase'?`<label class="field">Costo unitario<input class="tx-price" data-id="${l.id}" type="number" min="0" step="0.01" value="${l.price}" required></label>`:''}<button class="icon-button" type="button" data-action="tx-remove" data-id="${l.id}" aria-label="Quitar producto">×</button></div>`).join('')}</div>${area('note',kind==='purchase'?'Notas (opcional)':'Motivo obligatorio',state.txDraft.note||'',kind!=='purchase')}<p class="form-note">${kind==='purchase'?'El impuesto general del negocio se aplica al total de la compra. ':''}Las cantidades se validan de nuevo al confirmar.</p>`,'Confirmar '+(kind==='purchase'?'compra':kind==='transfer'?'traslado':'ajuste')),'Cada operación conserva su historial.',true)}
function invoiceDetail(id){const i=state.data.invoices.find(i=>i.id===num(id));if(!i)return;const d=state.data.documents.find(d=>d.id===i.document);openModal(i.number,`<div class="invoice-detail">${pill(...statuses[i.status])}<div class="invoice-parties"><div><small>EMISOR</small><h3>${esc(i.issuer.name)}</h3><p>${esc(i.issuer.address)}</p><small>${esc(i.issuer.tax_id)}</small></div><div><small>CLIENTE</small><h3>${esc(i.customer.name)}</h3><p>${esc(i.customer.address)}</p><small>${esc(i.customer.tax_id)}</small></div></div>${d?`<div class="table-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th class="numeric">Total</th></tr></thead><tbody>${d.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${fmt(l.quantity)} ${esc(l.unit)}</td><td class="numeric">${money(l.total)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="totals"><div><span>Subtotal</span><b>${money(i.subtotal)}</b></div><div><span>Impuestos</span><b>${money(i.tax)}</b></div><div class="grand-total"><span>Total</span><strong>${money(i.total)}</strong></div><div><span>Saldo pendiente</span><b>${money(i.balance)}</b></div></div><div class="dialog-actions"><a class="button secondary" href="/api/b/${state.id}/invoices/${i.id}/pdf/" target="_blank" rel="noopener">${icon('download',17)}Abrir / imprimir PDF</a>${num(i.balance)>0?button('Registrar cobro','payment',i.id,'primary','wallet'):''}</div><h3 class="spaced">Historial de cobros</h3>${i.payments.length?i.payments.map(p=>`<div class="detail-line"><div><b>${money(p.amount)} · ${methods[p.method]}</b><small>${dateLabel(p.date)} · ${esc(p.reference||'Sin referencia')}${p.voided?' · Anulado: '+esc(p.void_reason):''}</small></div>${admin()&&!p.voided?button('Anular / reembolso','void-payment',p.id,'secondary'):''}</div>`).join(''):'<p class="muted spaced">Todavía no hay cobros registrados.</p>'}</div>`,'Documento comercial · '+dateLabel(i.date),true)}
function paymentModal(id){const i=state.data.invoices.find(i=>i.id===num(id));state.editId=i.id;state.draftKey=crypto.randomUUID();openModal('Registrar cobro',form('payment-form',`<div class="balance-card"><span>${esc(i.number)} · ${esc(i.customer.name)}</span><strong>${money(i.balance)}</strong><small>Saldo pendiente</small></div>`+input('amount','Importe recibido',i.balance,'number',`required min="0.01" step="0.01" max="${i.balance}"`)+select('method','Método',[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia']])+input('reference','Referencia (opcional)')+'<p class="form-note">Registra un pago que ya recibiste. Nexo no cobra tarjetas ni mueve dinero.</p>','Guardar cobro'))}
function userModal(){openModal('Crear usuario',form('user-form',input('name','Nombre completo','','text','required maxlength="150"')+input('username','Usuario de acceso','','text','required maxlength="150" autocomplete="off"')+input('email','Correo (opcional)','','email')+select('role','Nivel de acceso',[['employee','Empleado'],['admin','Administrador']])+input('password','Contraseña temporal','','password','required minlength="12" autocomplete="new-password"')+'<p class="form-note">Comparte el acceso de forma privada. La persona tendrá que cambiar la contraseña temporal al iniciar sesión.</p>','Crear cuenta'))}
function permissionsModal(id){const u=state.data.users.find(u=>u.id===num(id));state.editId=u.id;openModal('Permisos de '+u.name,form('permissions-form',select('role','Rol',[['employee','Empleado'],['admin','Administrador']],u.role)+select('active','Acceso a este negocio',[['true','Activo'],['false','Desactivado']],String(u.active)),'Guardar permisos'))}
async function save(action,data){if(state.saving)return;state.saving=true;setError('',true);const buttons=[...document.querySelectorAll('#modal button[type=submit],#page button[type=submit]')];buttons.forEach(b=>b.disabled=true);try{const result=await api(`/api/b/${state.id}/action/`,{method:'POST',body:JSON.stringify({action,data})});state.saving=false;closeModal();if(action==='document'&&data.kind==='sale'){state.cart=[];state.cartKey=null;state.cartNote='';state.view='Facturación'}toast('Operación guardada');await initialize(state.id);if(result.invoice)invoiceDetail(result.invoice);return result}catch(e){setError(e.message,$('#modal').open);if(!$('#modal').open)toast(e.message);return null}finally{state.saving=false;buttons.forEach(b=>b.disabled=false)}}
function transactionData(fd){return {...fd,request_key:state.draftKey,kind:state.kind,lines:state.txLines.map(l=>({product:l.id,quantity:String(l.quantity),price:String(l.price)}))}}
function preserveCart(){const f=$('#sale-form');if(f){const fd=new FormData(f);state.cartWarehouse=fd.get('warehouse');state.cartContact=fd.get('contact');state.cartDue=fd.get('due_date');state.cartNote=fd.get('note')}}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const {action,id}=btn.dataset;try{
 if(action==='nav'){preserveCart();navigate(id)}
 else if(action==='menu')$('#sidebar').classList.toggle('is-open');
 else if(action==='refresh'){await initialize(state.id);toast('Inventario actualizado')}
 else if(action==='close-modal')closeModal();
 else if(action==='password')passwordModal();
 else if(action==='product')productModal(id);
 else if(action==='product-detail')productDetail(id);
 else if(action==='contact')contactModal(id);
 else if(action==='warehouse')warehouseModal(id);
 else if(action==='warehouse-stock'){const w=state.data.warehouses.find(w=>w.id===num(id));openModal(w.name,`<div class="table-scroll"><table><thead><tr><th>Producto</th><th>Existencias</th></tr></thead><tbody>${state.data.products.flatMap(p=>p.stocks.filter(s=>s.warehouse===w.id).map(s=>`<tr><td>${esc(p.name)}</td><td>${fmt(s.quantity)} ${esc(p.unit)}</td></tr>`)).join('')}</tbody></table></div>`,'Existencias por producto',true)}
 else if(action==='transaction')transactionModal(id);
 else if(action==='tx-remove'){saveTxDraft();state.txLines=state.txLines.filter(l=>l.id!==num(id));renderTransaction()}
 else if(action==='category'){preserveCart();state.category=id;render()}
 else if(action==='doc-filter'){state.filter=id;render()}
 else if(action==='sales-history')openModal('Mis ventas',docTable(state.data.documents.filter(d=>d.kind==='sale')),'Hasta las últimas 250 operaciones',true);
 else if(action==='cart-add'){preserveCart();const p=state.data.products.find(p=>p.id===num(id));const l=state.cart.find(l=>l.id===p.id);if(l)l.quantity+=1;else state.cart.push({id:p.id,name:p.name,unit:p.unit,price:num(p.price),quantity:1});state.cartKey=crypto.randomUUID();render();toast('Producto agregado')}
 else if(action==='cart-plus'||action==='cart-minus'||action==='cart-remove'){preserveCart();const l=state.cart.find(l=>l.id===num(id));if(action==='cart-remove')state.cart=state.cart.filter(l=>l.id!==num(id));else{l.quantity=Math.round((l.quantity+(action==='cart-plus'?1:-1))*1000)/1000;if(l.quantity<=0)state.cart=state.cart.filter(l=>l.id!==num(id))}state.cartKey=crypto.randomUUID();render()}
 else if(action==='cart-clear'){preserveCart();state.cart=[];state.cartKey=null;render()}
 else if(action==='invoice-detail')invoiceDetail(id);
 else if(action==='payment')paymentModal(id);
 else if(action==='document-detail'){const d=state.data.documents.find(d=>d.id===num(id));if(d.invoice_id){invoiceDetail(d.invoice_id)}else openModal(d.number,`<p>${kinds[d.kind]} · ${dateLabel(d.date)}</p><p class="muted">${esc(d.warehouse)} ${d.destination?'→ '+esc(d.destination):''}</p>${d.lines.map(l=>`<div class="detail-line"><span>${esc(l.name)}</span><b>${fmt(l.quantity)} ${esc(l.unit)}</b></div>`).join('')}<p class="spaced">${esc(d.note)}</p>`,'Registro de operación')}
 else if(action==='return'){state.editId=num(id);state.draftKey=crypto.randomUUID();openModal('Devolver venta completa',form('return-form',area('note','Motivo de la devolución','',true)+'<p class="adjust-note">Se repondrán todos los productos y se emitirá una nota de crédito. Si existen cobros, primero deben anularse o registrarse como reembolsados.</p>','Confirmar devolución'))}
 else if(action==='void-payment'){state.editId=num(id);openModal('Anular cobro / registrar reembolso',form('void-payment-form',area('reason','Motivo y referencia del reembolso','',true)+'<p class="adjust-note">Esto corrige el registro en Nexo. No devuelve dinero automáticamente; registra solo una corrección o un reembolso que hayas realizado.</p>','Confirmar anulación'))}
 else if(action==='archive'){state.editId=num(id);openModal('Cambiar estado del producto',form('archive-form','<p>El historial se conserva. Para archivar un producto, todas sus existencias deben estar en cero.</p>','Confirmar'))}
 else if(action==='user')userModal();else if(action==='permissions')permissionsModal(id);
 else if(action==='export')window.location.assign(`/api/b/${state.id}/export/?kind=${encodeURIComponent(id)}`);
 else if(action==='business')openModal('Crear negocio',form('business-form',input('name','Nombre del negocio','','text','required maxlength="120"')+select('sector','Tipo de negocio',sectors)+select('currency','Moneda',['USD','EUR','MXN','COP','PEN']),'Crear negocio'),'Tendrá su propio catálogo, almacenes, equipo e historial.');
 }catch(err){setError(err.message,$('#modal').open)}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){state.query=el.value;rerenderSearch()}if(el.classList.contains('tx-quantity')||el.classList.contains('tx-price')){const l=state.txLines.find(l=>l.id===num(el.dataset.id));l[el.classList.contains('tx-quantity')?'quantity':'price']=el.value}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='business-select'){state.cart=[];state.cartKey=null;state.id=num(el.value);state.query='';state.category='Todas';state.view='Resumen';await load()}if(el.id==='category-filter'){state.category=el.value;render()}if(el.id==='status-filter'){state.filter=el.value;render()}if(el.id==='tx-product'&&el.value){saveTxDraft();const p=state.data.products.find(p=>p.id===num(el.value));if(!state.txLines.some(l=>l.id===p.id))state.txLines.push({id:p.id,name:p.name,unit:p.unit,quantity:1,price:num(p.cost).toFixed(2)});renderTransaction()}if(el.classList.contains('cart-qty')){preserveCart();const l=state.cart.find(l=>l.id===num(el.dataset.id));l.quantity=num(el.value);state.cartKey=crypto.randomUUID();render()}if(el.closest('#sale-form')){preserveCart();state.cartKey=crypto.randomUUID()}}catch(err){setError(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id||f.id==='csrf-source')return;e.preventDefault();const fd=Object.fromEntries(new FormData(f));try{
 if(f.id==='product-form')await save('product',{...fd,...(state.editId?{id:state.editId,version:state.editVersion}:{})});
 else if(f.id==='contact-form')await save('contact',{...fd,id:state.editId});
 else if(f.id==='warehouse-form')await save('warehouse',{...fd,id:state.editId});
 else if(f.id==='transaction-form')await save('document',transactionData(fd));
 else if(f.id==='sale-form'){if(!state.cart.length)return;await save('document',{...fd,request_key:state.cartKey||=crypto.randomUUID(),kind:'sale',lines:state.cart.map(l=>({product:l.id,quantity:String(l.quantity),price:String(l.price)}))})}
 else if(f.id==='payment-form')await save('payment',{...fd,invoice:state.editId,request_key:state.draftKey});
 else if(f.id==='return-form')await save('return',{...fd,document:state.editId,request_key:state.draftKey});
 else if(f.id==='void-payment-form')await save('void_payment',{...fd,id:state.editId});
 else if(f.id==='archive-form')await save('archive',{id:state.editId});
 else if(f.id==='settings-form')await save('settings',fd);
 else if(f.id==='user-form')await save('user_create',fd);
 else if(f.id==='permissions-form')await save('user_update',{id:state.editId,role:fd.role,active:fd.active==='true'});
 else if(f.id==='business-form'){const r=await api('/api/businesses/',{method:'POST',body:JSON.stringify(fd)});closeModal();state.view='Resumen';await initialize(r.id);toast('Negocio creado')}
 else if(f.id==='password-form'){await api('/api/password/',{method:'POST',body:JSON.stringify(fd)});document.body.dataset.passwordRequired='false';closeModal();await initialize();toast('Contraseña actualizada')}
 else if(f.id==='photo-form'){await api(`/api/b/${state.id}/products/${f.dataset.id}/photo/`,{method:'POST',body:new FormData(f)});closeModal();await initialize();toast('Foto guardada')}
 else if(f.id==='report-form'){state.start=fd.start;state.end=fd.end;await load()}
 }catch(err){setError(err.message,$('#modal').open)}});
$('#modal').addEventListener('cancel',e=>{if(state.saving||document.body.dataset.passwordRequired==='true')e.preventDefault()});
if(document.body.dataset.passwordRequired==='true')passwordModal();else initialize();
